allmd={}
for r in roots:
    for p in glob.glob(r+'/**/*.md',recursive=True):
        rel=os.path.relpath(p,r).replace(os.sep,'/')[:-3]
        allmd.setdefault(os.path.basename(p)[:-3],[]).append(rel)
        allmd.setdefault(rel,[]).append(rel)
        parts=rel.split('/')
        if len(parts)>=2: allmd.setdefault('/'.join(parts[-2:]),[]).append(rel)
for f in scope:
    t=open(f,encoding='utf-8').read()
    for l in re.findall(r'\[\[([^\]|]+)',t):
        if l not in allmd: print('UNRESOLVED',f[:45],l)
    m=re.search(r'\*\*Example\*\* — (.{0,60})',t,re.S)
    ex=m.group(1).replace('\n',' ') if m else 'NONE'
    if 'Inference' not in ex: print('EXAMPLE',f[:55],'|',ex)
    for mm in re.finditer(r'(?i)\b(Verkhoshansky (states|describes|cites|reports|argues)|\bhe\b|\bhis own\b|the author\b)',t):
        s=t[max(0,mm.start()-60):mm.end()+40].replace('\n',' ')
        print('VOICE',f[:45],'|',s)
    for mm in re.finditer(r'research-papers/[^\s\x60,)]*',t): print('VAULTREF',f[:40],mm.group(0))
"

